-- Set B: 36 trap cases. Labels are written FIRST from the rule sheet (docs/RULE_SHEET.md); report text is generated afterwards
-- by a different model (claude-sonnet-4-5; extraction uses claude-haiku-4-5). Held out: not used to tune rules or prompts.
-- All cases: report date 2026-03-01, scored at sim_date 2026-10-04 (the DEMO_RESET(TRUE) state).
-- Patient defaults: 60-year-old male, former smoker, no history flags, clinic C3. Overrides are in patient_overrides.
-- evidence: NONE | CLAIM:<cpt>:<date> (payer share) | REPORT_DISCUSSES:<date> | REPORT_UNRELATED:<date> (hospital CT report)
USE ROLE ACCOUNTADMIN;
USE DATABASE FFU;

CREATE OR REPLACE TABLE EVAL.SETB_LABELS (
  case_id STRING, finding_no NUMBER, trap STRING, patient_overrides STRING, modality STRING, facts STRING, evidence STRING,
  expect_loop BOOLEAN, finding_type STRING, avg_mm NUMBER, aorta_cm FLOAT, tier NUMBER, action STRING, pathway STRING,
  expect_status STRING, why STRING);

